import os
import boto3

def extract_key_values(payload, config=None):
    config = config or {}
    client = boto3.client(
        "textract",
        region_name=config.get("region") or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
        aws_access_key_id=config.get("aws_access_key_id") or os.getenv("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=config.get("aws_secret_access_key") or os.getenv("AWS_SECRET_ACCESS_KEY"),
        aws_session_token=config.get("aws_session_token") or os.getenv("AWS_SESSION_TOKEN"),
    )
    if isinstance(payload, str):
        with open(payload, "rb") as f:
            document_bytes = f.read()
    elif isinstance(payload, (bytes, bytearray)):
        document_bytes = bytes(payload)
    elif isinstance(payload, dict) and "Bytes" in payload:
        document_bytes = payload["Bytes"]
    else:
        raise ValueError("payload must be a file path, bytes, or a dict containing 'Bytes'")

    response = client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["FORMS"]
    )

    blocks = response.get("Blocks", [])
    block_map = {block["Id"]: block for block in blocks}

    key_map = {}
    value_map = {}
    for block in blocks:
        if block.get("BlockType") == "KEY_VALUE_SET":
            entity_types = block.get("EntityTypes", [])
            if "KEY" in entity_types:
                key_map[block["Id"]] = block
            elif "VALUE" in entity_types:
                value_map[block["Id"]] = block

    def get_text(block):
        text_parts = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id, {})
                    if child.get("BlockType") == "WORD":
                        text_parts.append(child.get("Text", ""))
                    elif child.get("BlockType") == "SELECTION_ELEMENT":
                        if child.get("SelectionStatus") == "SELECTED":
                            text_parts.append("X")
        return " ".join(part for part in text_parts if part).strip()

    def find_value_block(key_block):
        for rel in key_block.get("Relationships", []):
            if rel.get("Type") == "VALUE":
                for value_id in rel.get("Ids", []):
                    if value_id in value_map:
                        return value_map[value_id]
        return None

    result = {}
    for key_block in key_map.values():
        key_text = get_text(key_block)
        if not key_text:
            continue
        value_block = find_value_block(key_block)
        value_text = get_text(value_block) if value_block else ""
        result[key_text] = value_text
    return result
